using System.ComponentModel;
using System.Text;
using System.Text.Json;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using OpenAI;

// ── Configuration ──────────────────────────────────────────────────────────────
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

// ── Services ───────────────────────────────────────────────────────────────────
var services = new ServiceCollection();
services.AddLogging(b => b.AddConsole().SetMinimumLevel(LogLevel.Warning));

services.AddChatClient(builder => builder
    .UseOpenAIChatClient(modelId, new OpenAIClient(apiKey)));

var sp = services.BuildServiceProvider();
var chatClient = sp.GetRequiredService<IChatClient>();
var loggerFactory = sp.GetRequiredService<ILoggerFactory>();

// ── Tools ──────────────────────────────────────────────────────────────────────
var notebook = new Notebook();

var tools = new AITool[]
{
    AIFunctionFactory.Create(WebSearchTool.SearchAsync),
    AIFunctionFactory.Create(
        ([Description("The text content of the note")] string content,
         [Description("A short title for the note")] string title) =>
        {
            notebook.AddNote(title, content);
            return $"Note saved: \"{title}\"";
        },
        name: "save_note",
        description: "Save a research note with a title and content. "
                   + "Use this to record key findings from web searches."),
    AIFunctionFactory.Create(
        () => notebook.GetAllNotes(),
        name: "get_notes",
        description: "Retrieve all saved research notes to review before writing a summary."),
};

// ── Agent ──────────────────────────────────────────────────────────────────────
var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research assistant. When given a topic:
        1. Use the web_search tool to search for information (perform 2-4 searches with varied queries).
        2. Use the save_note tool to record key findings from each search.
        3. Use the get_notes tool to review all your notes.
        4. Write a comprehensive summary of your research findings.
        Be thorough but concise. Cite sources when available.
        """,
    name: "ResearchAgent",
    description: "An agent that researches topics using web search and note-taking tools",
    tools: tools,
    loggerFactory: loggerFactory);

// ── Main loop ──────────────────────────────────────────────────────────────────
Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║       AI Research Agent              ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine("Enter a topic to research (or 'quit' to exit):\n");

var session = await agent.CreateSessionAsync();

while (true)
{
    Console.Write("Topic> ");
    var topic = Console.ReadLine();
    if (string.IsNullOrWhiteSpace(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    notebook.Clear();

    Console.WriteLine($"\nResearching: {topic}\n");

    try
    {
        var response = await agent.RunAsync(
            $"Research the following topic and provide a detailed summary: {topic}",
            session);

        Console.WriteLine("── Research Summary ─────────────────────────────────\n");
        Console.WriteLine(response.Text);
        Console.WriteLine("\n─────────────────────────────────────────────────────\n");
    }
    catch (Exception ex)
    {
        Console.WriteLine($"Error: {ex.Message}\n");
    }
}

Console.WriteLine("Goodbye!");

// ── Web search tool ────────────────────────────────────────────────────────────
static class WebSearchTool
{
    private static readonly HttpClient s_http = new()
    {
        DefaultRequestHeaders = { { "User-Agent", "ResearchAgent/1.0" } },
        Timeout = TimeSpan.FromSeconds(15),
    };

    [Description("Search the web for information on a query. Returns search results with titles, snippets, and URLs.")]
    public static async Task<string> SearchAsync(
        [Description("The search query string")] string query,
        CancellationToken cancellationToken = default)
    {
        // Use DuckDuckGo Instant Answer API (no key required)
        var encoded = Uri.EscapeDataString(query);
        var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";

        try
        {
            var json = await s_http.GetStringAsync(url, cancellationToken);
            using var doc = JsonDocument.Parse(json);
            var root = doc.RootElement;

            var sb = new StringBuilder();
            sb.AppendLine($"Search results for: \"{query}\"\n");

            // Abstract / main answer
            var heading = root.GetProperty("Heading").GetString();
            var abstractText = root.GetProperty("AbstractText").GetString();
            var abstractUrl = root.GetProperty("AbstractURL").GetString();

            if (!string.IsNullOrWhiteSpace(abstractText))
            {
                sb.AppendLine($"## {heading}");
                sb.AppendLine(abstractText);
                if (!string.IsNullOrWhiteSpace(abstractUrl))
                    sb.AppendLine($"Source: {abstractUrl}");
                sb.AppendLine();
            }

            // Related topics
            if (root.TryGetProperty("RelatedTopics", out var topics))
            {
                var count = 0;
                foreach (var topic in topics.EnumerateArray())
                {
                    if (count >= 5) break;

                    var text = topic.TryGetProperty("Text", out var t) ? t.GetString() : null;
                    var firstUrl = topic.TryGetProperty("FirstURL", out var u) ? u.GetString() : null;

                    if (!string.IsNullOrWhiteSpace(text))
                    {
                        sb.AppendLine($"- {text}");
                        if (!string.IsNullOrWhiteSpace(firstUrl))
                            sb.AppendLine($"  URL: {firstUrl}");
                        count++;
                    }
                }
            }

            var result = sb.ToString();
            return string.IsNullOrWhiteSpace(result.Trim())
                ? $"No detailed results found for \"{query}\". Try a more specific query."
                : result;
        }
        catch (Exception ex)
        {
            return $"Search failed for \"{query}\": {ex.Message}";
        }
    }
}

// ── Notebook for storing research notes ────────────────────────────────────────
class Notebook
{
    private readonly List<(string Title, string Content, DateTime Timestamp)> _notes = [];

    public void AddNote(string title, string content)
    {
        _notes.Add((title, content, DateTime.UtcNow));
    }

    public string GetAllNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        var sb = new StringBuilder();
        for (var i = 0; i < _notes.Count; i++)
        {
            var (title, content, ts) = _notes[i];
            sb.AppendLine($"[Note {i + 1}] {title} ({ts:HH:mm:ss UTC})");
            sb.AppendLine(content);
            sb.AppendLine();
        }
        return sb.ToString();
    }

    public void Clear() => _notes.Clear();
}

